def require(ok, message):
    if not ok:
        raise ValueError(message)


def digest(raw):
    return hashlib.sha256(raw).hexdigest()


def encoded(value):
    return (json.dumps(value, indent=2, ensure_ascii=False, allow_nan=False) + "\n").encode()


def evidence_block(source, url, phrases):
    """Assertions must occur together in one URL-bound search/open result."""
    texts = "\n".join(c.get("text", "") for c in source["content"])
    blocks = texts.split("--------------------------------------------------------------------------------")
    matches = [b for b in blocks if "(" + url + ")" in b and all(p in b for p in phrases)]
    require(len(matches) == 1, "Missing or ambiguous URL-bound evidence: " + url)


def extract(args):
    root = args.root.resolve()
    paths = {p: root / p for p in PINS if "/" in p}
    paths.update(inventory=args.inventory, plugSets=args.shared_sources_dir / "bungie-plugsets.json",
                 manifest=args.shared_sources_dir / "manifest.json")
    paths.update({p: args.sources_dir / p for p in PINS if p.startswith("research")})
    require(paths.keys() == PINS.keys(), "Every consumed input must have an explicit SHA pin")
    raw, pins = {}, {}
    for key, path in paths.items():
        data = path.read_bytes()
        require(digest(data) == PINS[key], "Source SHA256 mismatch: " + key)
        raw[key] = data
        pins[key] = {"path": str(path.relative_to(root)) if path.is_relative_to(root) else str(path),
                     "sha256": PINS[key], "bytes": len(data)}
    data = {k: json.loads(v) for k, v in raw.items() if k.endswith(".json")
            or k in ("inventory", "plugSets", "manifest")}
    selected = data["art/weapons/w40/definitions.json"]
    inventory, plugsets = data["inventory"], data["plugSets"]
    require(len(selected) == len({w["id"] for w in selected})
            == len({w["bungieHash"] for w in selected}) == 63, "Expected 63 unique selected weapons")
    response = data["manifest"]
    require(response["ErrorCode"] == 1, "Manifest failed")
    manifest = response["Response"]
    inventory_path = "/common/destiny2_content/json/en/DestinyInventoryItemDefinition-" + SUFFIX
    plugsets_path = inventory_path.replace("DestinyInventoryItemDefinition-", "DestinyPlugSetDefinition-")
    require(manifest["version"] == VERSION
            and manifest["jsonWorldComponentContentPaths"]["en"]["DestinyInventoryItemDefinition"] == inventory_path
            and manifest["jsonWorldComponentContentPaths"]["en"]["DestinyPlugSetDefinition"] == plugsets_path,
            "Inventory and plug sets must share the exact pinned manifest")
    w40 = data["art/weapons/w40/provenance.json"]
    require(w40["manifest"] == {"version": VERSION, "path": inventory_path}
            and w40["cachedInventorySha256"] == PINS["inventory"]
            and w40["source"] == BUNGIE + inventory_path, "W40 provenance mismatch")

    definitions = []
    for h, kind in ((BASE, "Trait"), (DUPLICATE, "Trait"), (ENHANCED, "Enhanced Trait")):
        perk = inventory[str(h)]
        require(perk["hash"] == h and perk["displayProperties"]["name"] == "Outlaw"
                and perk["itemTypeDisplayName"] == kind and perk["itemType"] == 19
                and not perk["redacted"] and not perk["blacklisted"]
                and not perk["plug"]["isDummyPlug"], "Invalid Outlaw definition")
        definitions.append({"hash": h, "name": "Outlaw", "itemTypeDisplayName": kind,
                            "description": perk["displayProperties"]["description"]})

    rows, proofs, direct_options, alias_options, enhanced_options = [], [], [], [], []
    random_keys = set()
    for weapon in selected:
        item = inventory[str(weapon["bungieHash"])]
        require(item["hash"] == weapon["bungieHash"] and item["itemType"] == 3
                and not item["redacted"] and not item["blacklisted"]
                and {k: v["value"] for k, v in item["stats"]["stats"].items()} == weapon["stats"],
                "Selected official weapon/stat mismatch")
        sockets = item.get("sockets", {})
        trait_indexes = {n for c in sockets.get("socketCategories", [])
                         if c["socketCategoryHash"] == TRAIT_CATEGORY for n in c["socketIndexes"]}
        for index, socket in enumerate(sockets.get("socketEntries", [])):
            direct = {socket["singleInitialItemHash"],
                      *[p["plugItemHash"] for p in socket.get("reusablePlugItems", [])]}
            for h, output in ((BASE, direct_options), (DUPLICATE, alias_options), (ENHANCED, enhanced_options)):
                if h in direct:
                    output.append({"id": weapon["id"], "hash": item["hash"], "socket": index,
                                   "perkHash": h, "source": "direct",
                                   "initialPerk": socket["singleInitialItemHash"] == h})
            for field in ("randomizedPlugSetHash", "reusablePlugSetHash"):
                set_hash = socket.get(field)
                if not set_hash:
                    continue
                pool = plugsets[str(set_hash)]
                require(pool["hash"] == set_hash and not pool["redacted"] and not pool["blacklisted"],
                        "Invalid or missing referenced plug set")
                entries = pool.get("reusablePlugItems", [])
                for h, output in ((DUPLICATE, alias_options), (ENHANCED, enhanced_options)):
                    if any(p["plugItemHash"] == h for p in entries):
                        output.append({"id": weapon["id"], "hash": item["hash"], "socket": index,
                                       "perkHash": h, "source": field, "plugSetHash": set_hash})
                matches = [(n, p) for n, p in enumerate(entries)
                           if p["plugItemHash"] == BASE and p.get("currentlyCanRoll") is True]
                if field != "randomizedPlugSetHash" or not matches:
                    continue
                require(index in trait_indexes and not pool["isFakePlugSet"]
                        and weapon["exotic"] is False and item["inventory"]["tierType"] != 6
                        and item["itemTypeDisplayName"] != "Sword", "Not a real randomized legendary trait pool")
                require(len(matches) == (2 if weapon["id"] == "apostate" else 1)
                        and all(p == matches[0][1] for _, p in matches),
                        "Only Apostate's two identical pool entries may be deduplicated")
                row = {"id": weapon["id"], "hash": item["hash"], "socket": index,
                       "perkHash": BASE, "plugSetHash": set_hash}
                rows.append(row)
                random_keys.add((row["id"], row["hash"], index, set_hash))
                proofs.append({**row, "selection": "randomized", "socketCategoryHash": TRAIT_CATEGORY,
                               "socketEntry": socket, "plugSetField": field, "isFakePlugSet": False,
                               "matchingEntries": [{"index": n, "item": p} for n, p in matches]})
            if weapon["id"] == "halfdan_d" and index == 3:
                require(item["hash"] == 3778520450 and index in trait_indexes and not weapon["exotic"]
                        and item["inventory"]["tierType"] == 5 and item["itemTypeDisplayName"] == "Auto Rifle"
                        and socket["singleInitialItemHash"] == BASE
                        and socket.get("reusablePlugSetHash") == 650
                        and not socket.get("randomizedPlugSetHash"), "Fixed Halfdan-D proof mismatch")
                pool = plugsets["650"]
                require(pool["hash"] == 650 and pool["isFakePlugSet"] is True
                        and len(pool["reusablePlugItems"]) == 1
                        and pool["reusablePlugItems"][0]["plugItemHash"] == BASE,
                        "Fixed Halfdan-D reusable set changed")
                row = {"id": "halfdan_d", "hash": 3778520450, "socket": 3,
                       "perkHash": BASE, "plugSetHash": 650}
                rows.append(row)
                proofs.append({**row, "selection": "fixedInitialTrait", "socketCategoryHash": TRAIT_CATEGORY,
                               "socketEntry": socket, "plugSetField": "reusablePlugSetHash",
                               "isFakePlugSet": True, "matchingEntries": [{"index": 0, "item": pool["reusablePlugItems"][0]}],
                               "reason": "The selected item's own initial trait proves eligibility. Set 650 is a fake reusable set, never a randomized-roll claim."})
    require(random_keys == EXPECTED_RANDOM and len(rows) == len({r["id"] for r in rows}) == 13,
            "Expected exactly 12 randomized rows plus fixed Halfdan-D")
    require(not alias_options, "Duplicate-base selected evidence changed: review and support proven aliases")
    require(enhanced_options == [{"id": "austringer", "hash": 3055790362, "socket": 3,
                                 "perkHash": ENHANCED, "source": "randomizedPlugSetHash", "plugSetHash": 2750499928}],
            "Enhanced Outlaw options changed; never silently accept enhanced")

    kc = data["src/main/resources/destiny/weapons/w61-kill-clip.json"]
    require(kc["stage"] == "W61" and kc["perk"]["hash"] == KC and len(kc["weapons"]) == 13,
            "W61 cross-check mismatch")
    for k in kc["weapons"]:
        item = inventory[str(k["hash"])]
        socket = item["sockets"]["socketEntries"][k["socket"]]
        pool = plugsets[str(k["plugSetHash"])]
        trait_indexes = {n for c in item["sockets"]["socketCategories"]
                         if c["socketCategoryHash"] == TRAIT_CATEGORY for n in c["socketIndexes"]}
        require(k["perkHash"] == KC and k["socket"] in trait_indexes, "W61 non-trait row")
        if k["id"] == "antiope_d":
            require(k["hash"] == 566976653 and k["socket"] == 3 and k["plugSetHash"] == 669
                    and socket["singleInitialItemHash"] == KC and socket["reusablePlugSetHash"] == 669
                    and pool["isFakePlugSet"], "W61 fixed proof changed")
        else:
            require(socket["randomizedPlugSetHash"] == k["plugSetHash"] and not pool["isFakePlugSet"]
                    and any(p["plugItemHash"] == KC and p.get("currentlyCanRoll") is True
                            for p in pool["reusablePlugItems"]), "W61 pool evidence changed")
    dual = [{"id": o["id"], "hash": o["hash"], "outlawSocket": o["socket"],
             "outlawPlugSetHash": o["plugSetHash"], "killClipSocket": k["socket"],
             "killClipPlugSetHash": k["plugSetHash"]}
            for o in rows for k in kc["weapons"] if o["hash"] == k["hash"] and o["socket"] != k["socket"]]
    require(len(dual) == 7 and {d["id"] for d in dual} == EXPECTED_DUAL, "KC coexistence candidates changed")

    evidence_block(data["research5.json"], OLD_PATCH_URL,
                   ["Destiny 2 Update 2.9.0", "Jun 9, 2020", "Reload stat: 0-100",
                    "Reload stat from +100 to +50.", "Reload duration scale from 0.8 to 0.9."])
    evidence_block(data["research2.json"], BUFF_PATCH_URL,
                   ["Destiny 2 Update 3.0.0.1", "Nov 10, 2020", "Outlaw",
                    "Increased Reload stat bonus from +50 to +70."])
    evidence_block(data["research7.json"], BASE_URL,
                   ["API ID: 1168162263", "Community Research", "70 Reload Speed",
                    "0.9x Reload Duration Multiplier for 6 seconds.", "Buff is removed on stow."])
    evidence_block(data["research7.json"], DUPLICATE_URL,
                   ["API ID: 1528281896", "Community Research", "70 Reload Speed", "6 seconds"])
    evidence_block(data["research7.json"], ENHANCED_URL,
                   ["API ID: 1347741687", "Enhanced Trait", "7 seconds"])
    evidence_block(data["research7.json"], SHELL_URL,
                   ["reload formula calculates how many frames each shell after the first shell takes",
                    "The first shell takes a significantly longer time"])

    mapping_source = data["art/weapons/w43/extraction.json"]
    mapping = {m["id"]: m for m in mapping_source["entries"]}
    formulas = data["art/weapons/w46/weapon_formulas.json"]
    base_timing = {t["id"]: t["timing"] for t in data["src/main/resources/destiny/weapons/w46-timing.json"]}
    by_id = {w["id"]: w for w in selected}
    calc = raw["art/weapons/w46/stat_calc.rs"].decode()
    require("reload_time = self.reload_data.solve_at(_reload_stat as f64)" in calc
            and "out.reload_time *= modifiers.reload_time_scale;" in calc
            and "reload_stat.clamp(0, 85)" in calc
            and "self.evpp * _x * _x + self.vpp * _x + self.offset" in raw["art/weapons/w46/rs_types.rs"].decode()
            and "pub type Seconds = f64;" in raw["art/weapons/w46/d2_enums.rs"].decode(),
            "W46 cached calculation semantics changed")
    require("new Plan(fallbackTicks, fallbackTicks, shellReload ? 1 : 0)" in
            raw["src/main/java/kim/biryeong/destiny/weapon/WeaponReloadPolicy.java"].decode(),
            "Authored first-shell fallback changed; reconcile explicitly")
    reloads, timing_audit = [], []
    for row in rows:
        w, m, t = by_id[row["id"]], mapping[row["id"]], base_timing[row["id"]]
        family = m["family"].lower().replace(" ", "_")
        require(family not in ("bow", "sword") and t["supported"], "Unexpected family: review bow-specific curve/scalar semantics")
        curve = formulas[m["family"]]["cat"][m["category"]]["reload"]
        require(set(curve) <= {"evpp", "vpp", "offset", "ammo_percent"}, "Unexpected reload curve fields")
        base = w["stats"][RELOAD_STAT]
        require(type(base) is int and 0 <= base <= 100, "Unsafe official Reload Speed stat")
        effective = min(100, base + 70)
        solve = lambda x: curve.get("evpp", 0) * x * x + curve.get("vpp", 0) * x + curve["offset"]
        base_seconds, effective_curve_seconds = solve(base), solve(effective)
        seconds = effective_curve_seconds * 0.9
        require(all(math.isfinite(x) and x > 0 for x in (base_seconds, effective_curve_seconds, seconds)), "Invalid reload duration")
        ticks = math.ceil(seconds * 20)
        base_ticks = math.ceil(base_seconds * 20)
        require(base_ticks == t["reloadPerRoundTicks" if t["shellReload"] else "reloadTicks"],
                "W46 base timing reproduction mismatch")
        r = {"id": row["id"], "firstTicks": ticks, "intervalTicks": ticks,
             "baseReloadStat": base, "effectiveReloadStat": effective}
        reloads.append(r)
        timing_audit.append({**r, "hash": row["hash"], "family": family,
                             "oracleFamily": m["family"], "category": m["category"], "subfamily": m["subfamily"],
                             "reloadStatHash": int(RELOAD_STAT), "curveReloadStat": effective,
                             "curve": curve, "baseSeconds": base_seconds, "baseTicks": base_ticks,
                             "effectiveCurveSeconds": effective_curve_seconds, "effectiveSeconds": seconds,
                             "durationMultiplier": 0.9, "rounding": "ceil(seconds * 20), once after stat and scalar",
                             "shellReload": t["shellReload"], "roundsPerInsert": 1 if t["shellReload"] else 0,
                             "firstDelayClassification": "AUTHORED_EQUAL_TO_INTERVAL_NOT_MEASURED" if t["shellReload"] else "HISTORICAL_W46_CURVE",
                             "intervalClassification": "HISTORICAL_COMMUNITY_APPROXIMATION",
                             "warning": "Curve describes repeat shell insertion; firstTicks mirrors existing fallback, not a measured initial delay." if t["shellReload"]
                             else "W46 historical curve approximates full reload; ammo-transfer point is not independently timed here."})
    require(len(reloads) == 13 and {r["id"] for r in reloads} == {r["id"] for r in rows}, "Reload coverage mismatch")

    mechanics = {
        "stage": "W62", "baseHash": BASE, "provenBaseHashes": [BASE],
        "duplicateBaseHash": DUPLICATE, "duplicateSelectedOccurrences": 0,
        "enhancedHashExcluded": ENHANCED, "reloadBonus": 70, "durationMultiplier": 0.9,
        "durationSeconds": 6, "durationTicks": 120, "ticksPerSecond": 20,
        "trigger": {"event": "precision weapon final blow", "source": "Official selected base trait description",
                    "requiresReloadForActivation": False,
                    "integrationBoundary": "Activate at the confirmed damaging transaction's critical final blow; hit, body kill, or unrelated ability kill does not qualify."},
        "primaryHistory": [
            {"url": OLD_PATCH_URL, "publisher": "Bungie", "primary": True,
             "title": "Destiny 2 Update 2.9.0", "publishedAt": "2020-06-09",
             "reloadBonusBefore": 100, "reloadBonusAfter": 50,
             "durationMultiplierBefore": 0.8, "durationMultiplierAfter": 0.9,
             "supports": ["Historical nerf only: +50 is superseded by 3.0.0.1", "Reload stat range 0 to 100", "Scalar acts in addition to the capped archetype-specific stat"],
             "privateCapture": "research5.json", "retrieval": "URL-bound official page search-index body; ordinary HTTP returned only an app shell."},
            {"url": BUFF_PATCH_URL, "publisher": "Bungie", "primary": True,
             "title": "Destiny 2 Update 3.0.0.1", "publishedAt": "2020-11-10",
             "reloadBonusBefore": 50, "reloadBonusAfter": 70,
             "supports": ["Later +70 stat buff"], "doesNotEstablish": ["Six-second duration", "Stow cancellation", "Phase snapshot semantics"],
             "privateCapture": "research2.json", "retrieval": "URL-bound opened official article in web tool; ordinary HTTP returned only an app shell."}],
        "communityMeasurements": {"url": BASE_URL, "publisher": "light.gg", "primary": False,
                                  "section": "Community Research", "privateCapture": "research7.json",
                                  "lastUpdatedReported": "2024-07-28", "reloadBonus": 70, "durationMultiplier": 0.9,
                                  "durationSeconds": 6, "stowRemovesBuff": True,
                                  "retrieval": "Search-index body bound to exact Korean base-hash URL; direct web fetch returned 402, ordinary HTTP returned 403. Search crawl is not a fresh gameplay measurement."},
        "enhancedComparison": {"hash": ENHANCED, "url": ENHANCED_URL, "primary": False,
                               "durationSeconds": 7, "implemented": False,
                               "selectedOptions": enhanced_options},
        "duplicateBaseAudit": {"hash": DUPLICATE, "url": DUPLICATE_URL,
                               "officialKind": "Trait", "selectedOccurrences": alias_options,
                               "policy": "Audit direct/initial and both referenced pool kinds for every selected socket. Include proven base aliases after explicit allowlist review; none occur in this pinned selection."},
        "reloadFormula": {"effectiveReloadStat": "min(100, baseReloadStat + 70)",
                          "seconds": "0.9 * (evpp * effectiveReloadStat^2 + vpp * effectiveReloadStat + offset)",
                          "ticks": "ceil(seconds * 20)", "statSource": "Official selected W40 Reload Speed 4188031367",
                          "curveSource": "W46 cached oracle_engine weapon_formulas.json, verified against stat_calc.rs and rs_types.rs",
                          "bowBoundary": "No selected Outlaw bow. Do not confuse effective stat cap100 with Oracle bow curve clamp85 or its special scalar formula.",
                          "precision": "Evaluate unrounded seconds at modified stat, apply0.9, ceil once. Multiplying old integer ticks by0.9 ignores +70 and is invalid.",
                          "currentness": "This is the current W62 contract using pinned historical W46 approximations, not a current live Destiny sandbox certification."},
        "shellResearch": {"url": SHELL_URL, "author": "VanHolden304", "primary": False,
                          "classification": "Community tester's historical first-hand account, 2020; not Bungie",
                          "privateCapture": "research7.json", "repeatFormulaOnly": True,
                          "initialDelayMeasured": False,
                          "finding": "The tester times repeat insertions with the quadratic and reports a longer initial insertion without exact initial measurements. Their pre-November2020 Outlaw stat values are not used.",
                          "runtimePolicy": "firstTicks equals intervalTicks to preserve existing WeaponReloadPolicy fallback. Both selected shotguns use9ticks; only the repeat interval is supported by the curve model."},
        "animationSnapshot": {"verifiedDestinyBehavior": False,
                              "policy": "Snapshot phase durations at reload start. Each new timed reload can use Outlaw while the buff is active; an already-started phase keeps its captured deadline.",
                              "boundary": "Authored integration policy. Retrieved sources do not establish mid-animation expiration, activation during reload, or per-shell re-evaluation; do not infer these from the six-second buff duration."},
        "mixedPelletPrecision": {"verified": False,
                                 "nonSlugCandidate": {"id": "parcel_of_stardust_fell_to_earth", "hash": 2217366863,
                                                      "socket": 4, "plugSetHash": 3424940310},
                                 "boundary": "Pool proves non-slug eligibility, not whether a mixed body/precision pellet volley counts as a precision kill. Use the runtime's actual critical final-blow transaction; that classification is a project policy until independently verified."},
        "refreshAndConsumption": {"verified": False,
                                  "policy": "A fresh qualifying precision final blow resets the deadline to now+120. Reloads neither consume the buff nor extend it; stow clears it.",
                                  "boundary": "Repeated-kill refresh and non-consumption are integration choices consistent with a timed precision-kill buff, not separately measured here."},
        "limitations": ["No live gameplay tests or exhaustive later-patch audit.", "Pool availability is optional-roll eligibility, not automatic equipment.",
                        "No enhanced, catalyst, same-name reissue, exotic or sword inferred.",
                        "No armor, magazine, masterwork, other perks, frame-specific extra scalar or empty-mag modifier simulated.",
                        "No verified exact first-shell delay, animation snapshot, tick endpoint or mixed-pellet classification."]}
    coverage = {r["id"] for r in rows}
    pools = {"stage": "W62", "selectedCount": 63, "supportedCount": 13, "poolRows": 13,
             "randomizedPoolRows": 12, "fixedDirectRows": 1, "perkDefinitions": definitions,
             "provenBaseHashes": [BASE], "duplicateBaseSelectedOptions": alias_options,
             "enhancedSelectedOptionsExcluded": enhanced_options, "directSocketOptions": direct_options,
             "policy": "Exact selected hashes; zero-based trait socket. Random pools require currentlyCanRoll=true and non-fake randomizedPlugSetHash. Weight0 does not exclude a currently-rollable item. Fixed Halfdan-D is supported only by its own initial trait, never by pretending fake set650 is randomized.",
             "weapons": proofs, "dualOutlawKillClipCandidates": dual,
             "sameSocketConflict": [{"id": "chattering_bone", "hash": 568515759, "socket": 3, "plugSetHash": 216806616,
                                     "reason": "Both perks share one trait socket; not a simultaneous-roll candidate."}],
             "duplicatePoolEntries": [{"id": "apostate", "hash": 2164448701, "socket": 3, "plugSetHash": 1306932196,
                                       "perkHash": BASE, "rawMatchingEntryCount": 2, "emittedRows": 1}],
             "unsupportedSelectedIds": [w["id"] for w in selected if w["id"] not in coverage]}
    timing = {"stage": "W62", "repository": mapping_source["repository"], "commit": mapping_source["commit"],
              "commitDate": mapping_source["commitDate"], "source": "build_resources/weapon_formulas.json",
              "licenseSources": ["art/weapons/w46/MIT-LICENSE", "art/weapons/w46/UNLICENSE"],
              "formula": mechanics["reloadFormula"], "snapshot": mechanics["animationSnapshot"],
              "limitations": mechanics["limitations"], "entries": timing_audit}
    resource = {"stage": "W62", "perk": {"id": "outlaw", "hash": BASE, "durationTicks": 120,
                "reloadBonus": 70, "durationMultiplier": 0.9, "timingSource": REF + "reload-timings.json"},
                "weapons": rows, "reloads": reloads}
    provenance = {"stage": "W62", "manifestVersion": VERSION,
                  "inventoryUrl": BUNGIE + inventory_path, "plugSetsUrl": BUNGIE + plugsets_path,
                  "sourceHashes": pins, "generator": SCRIPT, "generatorSha256": digest((root / SCRIPT).read_bytes()),
                  "runtimeSha256": digest(encoded(resource)), "retrievedAtDate": "2026-10-24",
                  "sourceBoundary": "Official inventory/PlugSets prove eligibility and raw stats; Bungie2.9.0 proves historical +50/0.9 and cap100;3.0.0.1 supersedes +50 with +70. Exact-base light.gg community research supplies6seconds/stow. W46 Oracle quadratics approximate modified timing. Phase snapshots and first-shell fallback remain authored.",
                  "privateSources": "Raw web tool responses and HTTP app shells remain /tmp/destiny-weapons-w62. No full articles or search captures are emitted.",
                  "reproduce": "rtk proxy python3 scripts/extract_outlaw_w62.py --verify",
                  "disjointReproduce": "rtk proxy python3 scripts/extract_outlaw_w62.py --output-root /tmp/destiny-weapons-w62/reproduced",
                  "verification": "Offline, every consumed input SHA pinned; missing/mutated input fails closed. --verify compares all generated bytes and never creates directories, writes files or uses network IO."}
    return {TARGET: resource, REF + "socket-pools.json": pools, REF + "mechanics.json": mechanics,
            REF + "reload-timings.json": timing, REF + "provenance.json": provenance}, paths


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--verify", action="store_true")
    parser.add_argument("--root", type=Path, default=ROOT, help="Read-only input checkout")
    parser.add_argument("--output-root", type=Path, help="Separate output checkout/tree; does not change generated bytes")
    parser.add_argument("--inventory", type=Path, default=Path("/tmp/destiny-weapons-w30/bungie-items.json"))
    parser.add_argument("--shared-sources-dir", type=Path, default=Path("/tmp/destiny-weapons-w60"))
    parser.add_argument("--sources-dir", type=Path, default=Path("/tmp/destiny-weapons-w62"))
    args = parser.parse_args()
    try:
        outputs, inputs = extract(args)
        output_root = (args.output_root or args.root).resolve()
        input_paths = {p.resolve() for p in inputs.values()} | {(args.root / SCRIPT).resolve()}
        for name in outputs:
            path = (output_root / name).resolve()
            require(path.is_relative_to(output_root) and path not in input_paths,
                    "Output path aliases or escapes an input: " + name)
        if args.verify:
            for name, value in outputs.items():
                require((output_root / name).read_bytes() == encoded(value), "Generated bytes differ: " + name)
        else:
            for name, value in outputs.items():
                path = output_root / name
                path.parent.mkdir(parents=True, exist_ok=True)
                path.write_bytes(encoded(value))
        print(("VERIFIED" if args.verify else "GENERATED") + ": W62;63 selected;13 weapons/reloads=12 randomized+1 fixed Halfdan-D;7 KC coexistence candidates;duplicate-base0;enhanced1 excluded.")
        print("Reload ticks: Duke33 Austringer33 Halfdan23 Bygones24 Chattering24 Blast24 Claws24 Distant25 Lonesome22 DeadMan21 Apostate40 FILO9 Parcel9. Shotgun first9 is authored, repeat9 is curve-derived.")
    except (OSError, ValueError, KeyError, TypeError) as error:
        print("W62 extraction failed: " + str(error), file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
